package promptbeast

import org.junit.jupiter.api.Test
import kotlin.test.assertTrue

/** Every suite replays vectors generated by the Python reference core (see tools/ in the PromptBeast repo). */
class GoldenTest {
    private fun run(rep: GoldenSuite.Report) {
        println(rep)
        assertTrue(rep.failures.isEmpty(), "$rep:\n" + rep.failures.joinToString("\n"))
        assertTrue(rep.checked > 0, "${rep.name}: nothing was checked")
    }

    @Test fun rng() = run(GoldenSuite.rng())
    @Test fun charclass() = run(GoldenSuite.charclass())
    @Test fun dsl() = run(GoldenSuite.dsl())
    @Test fun weights() = run(GoldenSuite.weights())
    @Test fun articles() = run(GoldenSuite.articles())
    @Test fun profiles() = run(GoldenSuite.profiles())
    @Test fun compose() = run(GoldenSuite.compose())
    @Test fun lint() = run(GoldenSuite.lint())
    @Test fun export() = run(GoldenSuite.export())
    @Test fun forge() = run(GoldenSuite.forge())
    @Test fun library() = run(GoldenSuite.library())
    @Test fun mackbridge() = run(GoldenSuite.mackbridge())
    @Test fun ai() = run(GoldenSuite.ai())
    @Test fun aiHttp() = run(AiHttpSuite.run())
    @Test fun userPacks() = run(UserPacksSuite.run())
}
